+const DEFAULT_LIMIT = 20;
+const MAX_LIMIT = 100;
+
+function clampLimit(raw) {
+  const n = Math.trunc(Number(raw));
+  return Math.min(Math.max(n || DEFAULT_LIMIT, 1), MAX_LIMIT);
+}
+
+module.exports = { clampLimit, DEFAULT_LIMIT, MAX_LIMIT };
