+test('missing, zero and junk limits mean 20', () => {
+  assert.strictEqual(clampLimit(undefined), 20);
+  assert.strictEqual(clampLimit('0'), 20);
+  assert.strictEqual(clampLimit('ten'), 20);
+});
+
+test('limits are clamped to 1..100', () => {
+  assert.strictEqual(clampLimit('500'), 100);
+  assert.strictEqual(clampLimit('-3'), 1);
